// ============================================================
// quant_scatter op_host — Host 端 tiling + EXEC_KERNEL_CMD 启动
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_quant_scatter.h"

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;
constexpr int64_t CACHE_LINE_BYTES = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;

// Tiling 数据结构体
struct QuantScatterTilingData {
    int64_t outerSize;
    int64_t innerSize;
    int64_t axisSize;
    int64_t updateAxisSize;
    int64_t tileSize;
};

at::Tensor quant_scatter(
    const at::Tensor &input,
    const at::Tensor &indices,
    const at::Tensor &updates,
    const at::Tensor &quant_scales,
    c10::optional<at::Tensor> quant_zero_points,
    int64_t axis,
    int64_t quant_axis,
    c10::optional<std::string> reduce)
{
    // ---- 输入校验 ----
    TORCH_CHECK(input.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: input must be on NPU device");
    TORCH_CHECK(indices.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: indices must be on NPU device");
    TORCH_CHECK(updates.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: updates must be on NPU device");
    TORCH_CHECK(quant_scales.device().type() == at::DeviceType::PrivateUse1,
                "quant_scatter: quant_scales must be on NPU device");

    TORCH_CHECK(input.scalar_type() == at::kChar,
                "quant_scatter: input must be int8");
    TORCH_CHECK(indices.scalar_type() == at::kInt,
                "quant_scatter: indices must be int32");
    TORCH_CHECK(updates.scalar_type() == at::kHalf ||
                updates.scalar_type() == at::kBFloat16,
                "quant_scatter: updates must be float16 or bfloat16");
    TORCH_CHECK(quant_scales.scalar_type() == at::kFloat ||
                quant_scales.scalar_type() == at::kBFloat16,
                "quant_scatter: quant_scales must be float32 or bfloat16");

    int64_t ndim = input.dim();
    if (axis < 0) axis += ndim;
    TORCH_CHECK(axis >= 0 && axis < ndim,
                "quant_scatter: axis out of range");

    bool hasZp = quant_zero_points.has_value();
    if (hasZp) {
        auto zp = quant_zero_points.value();
        TORCH_CHECK(zp.device().type() == at::DeviceType::PrivateUse1,
                    "quant_scatter: quant_zero_points must be on NPU device");
        TORCH_CHECK(zp.scalar_type() == at::kInt ||
                    zp.scalar_type() == at::kBFloat16,
                    "quant_scatter: quant_zero_points must be int32 or bfloat16");
    }

    // ---- 连续化 ----
    at::Tensor inputContiguous = input.contiguous();
    at::Tensor indicesContiguous = indices.contiguous();
    at::Tensor updatesContiguous = updates.contiguous();
    at::Tensor scalesContiguous = quant_scales.contiguous();

    at::Tensor zpContiguous;
    if (hasZp) {
        zpContiguous = quant_zero_points.value().contiguous();
    }

    // ---- 维度参数 ----
    // axis 之前维度之积 = outerSize (batch 数)
    int64_t outerSize = 1;
    for (int64_t i = 0; i < axis; i++) {
        outerSize *= inputContiguous.size(i);
    }

    // axis 维度大小 (M)
    int64_t axisSizeVal = inputContiguous.size(axis);

    // axis 之后维度之积 = innerSize (K, 量化维度)
    int64_t innerSize = 1;
    for (int64_t i = axis + 1; i < ndim; i++) {
        innerSize *= inputContiguous.size(i);
    }

    // updates 在 axis 维度的大小 (通常为 1)
    int64_t updateAxisSizeVal = updatesContiguous.size(axis);

    // indices 校验: 应为 1D, 长度等于 outerSize
    int64_t indicesNumel = indicesContiguous.numel();
    TORCH_CHECK(indicesNumel == outerSize,
                "quant_scatter: indices length must match outer size");

    // ---- 3D 视图 ----
    // input: [outerSize, axisSize, innerSize]
    auto input3d = inputContiguous.reshape({outerSize, axisSizeVal, innerSize});

    // updates: [outerSize, updateAxisSize, innerSize]
    auto updates3d = updatesContiguous.reshape({outerSize, updateAxisSizeVal, innerSize});

    // scales: 广播到 [1, 1, innerSize] 或已经是
    // 确保 scales 展开后有正确的 innerSize
    auto scalesFlat = scalesContiguous.reshape({-1});
    TORCH_CHECK(scalesFlat.numel() >= innerSize,
                "quant_scatter: scales size must be at least innerSize");

    // zp: 类似处理
    at::Tensor zpFlat;
    if (hasZp) {
        zpFlat = zpContiguous.reshape({-1});
        TORCH_CHECK(zpFlat.numel() >= innerSize,
                    "quant_scatter: zero_points size must be at least innerSize");
    } else {
        zpFlat = at::empty({innerSize},
            at::TensorOptions().dtype(at::kChar).device(input.device()));
    }

    // ---- output ----
    auto output = inputContiguous.clone();
    auto output3d = output.reshape({outerSize, axisSizeVal, innerSize});

    // ---- dtype 标志 ----
    bool updatesIsBf16Val = (updatesContiguous.scalar_type() == at::kBFloat16);
    int64_t updatesIsBf16 = updatesIsBf16Val ? 1 : 0;
    int64_t hasZpInt64 = hasZp ? 1 : 0;

    // ---- UB 级 tiling: 计算 tileSize ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // bufferCoefficient: 最坏情况 (fp16 路径 + 有 zp) = 26 bytes/element
    // fp16 路径 (T=half, T_SCALE=float, T_ZP=int32_t, HasZp=true):
    //   inQueueUpdates: 2*2=4, inQueueScales: 4*2=8, inQueueZp: 4*2=8
    //   tmpFp32Buf: 4, outQueueResult: 1*2=2
    //   Total per element: 4 + 8 + 8 + 4 + 2 = 26
    int64_t bufferCoefficient;
    if (hasZp) {
        bufferCoefficient = 26; // with zp
    } else {
        bufferCoefficient = 18; // without zp (fp16: 4+8+4+2=18)
    }

    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = UB_ALIGN_BYTES / 1; // int8 = 1 byte → 32 elements
    int64_t tileSize = (maxTileElements / alignElements) * alignElements;
    if (tileSize > innerSize) {
        tileSize = innerSize;
    }
    if (tileSize < 1) tileSize = 1;

    // ---- Block 级: 核间分配 (Mode B: 每核一行 scatter) ----
    // 每个 batch 一个任务, taskId 交错分配
    uint32_t blockDim = static_cast<uint32_t>(std::min(outerSize, MAX_CORES));
    if (blockDim < 1) blockDim = 1;

    // EXEC_KERNEL_CMD: 所有参数必须是左值
    int64_t outerSizeL = outerSize;
    int64_t innerSizeL = innerSize;
    int64_t axisSizeL = axisSizeVal;
    int64_t updateAxisSizeL = updateAxisSizeVal;
    int64_t tileSizeL = tileSize;
    int64_t updatesIsBf16L = updatesIsBf16;
    int64_t hasZpL = hasZpInt64;

    EXEC_KERNEL_CMD(quant_scatter, blockDim,
                    input3d, indicesContiguous, updates3d, scalesFlat, zpFlat, output3d,
                    outerSizeL, innerSizeL, axisSizeL, updateAxisSizeL, tileSizeL,
                    updatesIsBf16L, hasZpL);

    return output;
}

}  // namespace ascend_kernel
