import sys
from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "quant_scatter_ext*")

# 优先 whl import (触发 TORCH_LIBRARY 注册)
try:
    import quant_scatter_ext  # noqa: F401
except ImportError:
    # 兜底: 直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """AscendC 实现: 内部调用 torch.ops.npu.quant_scatter"""

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, input: torch.Tensor, indices: torch.Tensor,
                updates: torch.Tensor, quant_scales: torch.Tensor,
                quant_zero_points: torch.Tensor = None,
                axis: int = 0, quant_axis: int = 1,
                reduce: str = 'update') -> torch.Tensor:
        """调用自定义 AscendC 算子完成量化 scatter"""
        return torch.ops.npu.quant_scatter(
            input, indices, updates, quant_scales,
            quant_zero_points=quant_zero_points,
            axis=axis, quant_axis=quant_axis, reduce=reduce
        )
