31	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
32	class QuantScatterKernel {
33	public:
34	    __aicore__ inline QuantScatterKernel() {}
35	    __aicore__ inline void Init(GM_ADDR inputGm, GM_ADDR indicesGm,
36	                                 GM_ADDR updatesGm, GM_ADDR scalesGm,
37	                                 GM_ADDR zpGm, GM_ADDR outputGm,
38	                                 int64_t outerSize, int64_t innerSize,
39	                                 int64_t axisSize, int64_t updateAxisSize,
