50	    TPipe pipe;
51	    TQue<TPosition::VECIN, BUFFER_NUM> inQueueUpdates;
52	    TQue<TPosition::VECIN, BUFFER_NUM> inQueueScales;
53	    TQue<TPosition::VECIN, BUFFER_NUM> inQueueZp;
54	    TBuf<TPosition::VECCALC> tmpFp32Buf;
55	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueueResult;
