75	    GM_ADDR inputGm, GM_ADDR indicesGm, GM_ADDR updatesGm, GM_ADDR scalesGm,
76	    GM_ADDR zpGm, GM_ADDR outputGm,
77	    int64_t outerSize, int64_t innerSize,
