87	    // 尾块计算
88	    numTiles_ = (innerSize_ + tileSize_ - 1) / tileSize_;
89	    int64_t lastTileLen = innerSize_ - (numTiles_ - 1) * tileSize_;
90	    tailTileSize_ = (lastTileLen > 0) ? lastTileLen : tileSize_;
91	
92	    inputGm_.SetGlobalBuffer((__gm__ int8_t*)inputGm);
93	    indicesGm_.SetGlobalBuffer((__gm__ int32_t*)indicesGm);
94	    updatesGm_.SetGlobalBuffer((__gm__ T*)updatesGm);
95	    scalesGm_.SetGlobalBuffer((__gm__ T_SCALE*)scalesGm);
96	    zpGm_.SetGlobalBuffer((__gm__ T_ZP*)zpGm);
