102	    int64_t zpAligned = ((tileSize_ * sizeof(T_ZP) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
103	    int64_t tmpAligned = ((tileSize_ * sizeof(float) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
104	    int64_t outAligned = ((tileSize_ * sizeof(int8_t) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
