115	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
116	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::CopyIn(
117	    int64_t batchIdx, int64_t offset, int64_t curLen)
118	{
119	    // 1. 加载 updates tile: updates[batchIdx, 0, offset:]
120	    //    updates shape: [outerSize, updateAxisSize, innerSize], 且 updateAxisSize 通常为 1
121	    int64_t updOffset = batchIdx * updateAxisSize_ * innerSize_ + offset;
122	    LocalTensor<T> updatesLocal = inQueueUpdates.AllocTensor<T>();
123	    DataCopyExtParams updParams;
124	    updParams.blockCount = 1;
125	    updParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
126	    updParams.srcStride = 0;
127	    updParams.dstStride = 0;
128	    DataCopyPadExtParams<T> updPadParams;
129	    updPadParams.isPad = false;
130	    DataCopyPad(updatesLocal, updatesGm_[updOffset], updParams, updPadParams);
131	    inQueueUpdates.EnQue(updatesLocal);
132	
133	    // 2. 加载 scales tile: scales[0, 0, offset:] (broadcast along batch)
134	    LocalTensor<T_SCALE> scalesLocal = inQueueScales.AllocTensor<T_SCALE>();
135	    DataCopyExtParams sclParams;
136	    sclParams.blockCount = 1;
137	    sclParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T_SCALE));
138	    sclParams.srcStride = 0;
139	    sclParams.dstStride = 0;
140	    DataCopyPadExtParams<T_SCALE> sclPadParams;
141	    sclPadParams.isPad = false;
142	    DataCopyPad(scalesLocal, scalesGm_[offset], sclParams, sclPadParams);
143	    inQueueScales.EnQue(scalesLocal);
144	
145	    // 3. 加载 zero_points tile (if hasZp)
146	    if constexpr (HasZp) {
147	        LocalTensor<T_ZP> zpLocal = inQueueZp.AllocTensor<T_ZP>();
148	        DataCopyExtParams zpParams;
149	        zpParams.blockCount = 1;
150	        zpParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T_ZP));
151	        zpParams.srcStride = 0;
152	        zpParams.dstStride = 0;
153	        DataCopyPadExtParams<T_ZP> zpPadParams;
154	        zpPadParams.isPad = false;
