160	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
161	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Compute(int64_t curLen)
162	{
163	    // 1. DeQue updates, Cast 到 fp32
164	    LocalTensor<T> updatesLocal = inQueueUpdates.DeQue<T>();
165	    LocalTensor<float> updatesFp32 = tmpFp32Buf.Get<float>();
166	    Cast(updatesFp32, updatesLocal, RoundMode::CAST_NONE, curLen);
167	
168	    // 2. DeQue scales, 按需 Cast 到 fp32
169	    LocalTensor<T_SCALE> scalesLocal = inQueueScales.DeQue<T_SCALE>();
170	    LocalTensor<float> scalesFp32;
171	    if constexpr (ScalesIsFp32) {
172	        // scales 已是 fp32, 直接 reinterpret
173	        scalesFp32 = scalesLocal.template ReinterpretCast<float>();
174	    } else {
175	        // scales 是 bf16, Cast 到 fp32
176	        scalesFp32 = tmpFp32Buf.Get<float>();
177	        Cast(scalesFp32, scalesLocal, RoundMode::CAST_NONE, curLen);
178	    }
179	
180	    // 3. Quantize: Div(updates / scales)
181	    LocalTensor<float> quantFp32 = tmpFp32Buf.Get<float>();
182	    Div(quantFp32, updatesFp32, scalesFp32, curLen);
183	
184	    // 4. 如有 zp: Add(zp)
185	    if constexpr (HasZp) {
186	        LocalTensor<T_ZP> zpLocal = inQueueZp.DeQue<T_ZP>();
187	        LocalTensor<float> zpFp32 = tmpFp32Buf.Get<float>();
188	        Cast(zpFp32, zpLocal, RoundMode::CAST_NONE, curLen);
189	        Add(quantFp32, quantFp32, zpFp32, curLen);
190	        inQueueZp.FreeTensor(zpLocal);
191	    }
192	
193	    // 5. Cast fp32 → int8: 自动完成 round + clamp[-128,127] + inf 饱和
194	    LocalTensor<int8_t> resultInt8 = outQueueResult.AllocTensor<int8_t>();
195	    Cast(resultInt8, quantFp32, RoundMode::CAST_ROUND, curLen);
196	    outQueueResult.EnQue(resultInt8);
197	
198	    // 6. Free 输入
199	    inQueueUpdates.FreeTensor(updatesLocal);
200	    inQueueScales.FreeTensor(scalesLocal);
201	}
