221	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
222	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Process()
223	{
224	    int64_t blockIdx = GetBlockIdx();
225	    int64_t coreNum = (outerSize_ < MAX_CORES) ? outerSize_ : MAX_CORES;
226	    if (blockIdx >= coreNum) return;
227	
228	    // 核内循环: taskId 交错分配
229	    for (int64_t taskId = blockIdx; taskId < outerSize_; taskId += coreNum) {
230	        // 读取索引
231	        int32_t idxVal = indicesGm_.GetValue(taskId);
232	
233	        // 沿 innerSize 分 tile
234	        for (int64_t t = 0; t < numTiles_ - 1; ++t) {
235	            int64_t offset = t * tileSize_;
236	            CopyIn(taskId, offset, tileSize_);
237	            Compute(tileSize_);
238	            CopyOut(taskId, idxVal, offset, tileSize_);
239	        }
240	        // 尾 tile
241	        int64_t lastOffset = (numTiles_ - 1) * tileSize_;
242	        CopyIn(taskId, lastOffset, tailTileSize_);
243	        Compute(tailTileSize_);
244	        CopyOut(taskId, idxVal, lastOffset, tailTileSize_);
245	    }
246	}
