// ============================================================
// quant_scatter op_kernel — 量化 Scatter 算子
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;
constexpr int64_t UB_ALIGN_BYTES = 32;
constexpr int64_t MAX_CORES = 40;

template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
class QuantScatterKernel {
public:
    __aicore__ inline QuantScatterKernel() {}
    __aicore__ inline void Init(GM_ADDR inputGm, GM_ADDR indicesGm,
                                 GM_ADDR updatesGm, GM_ADDR scalesGm,
                                 GM_ADDR zpGm, GM_ADDR outputGm,
                                 int64_t outerSize, int64_t innerSize,
                                 int64_t axisSize, int64_t updateAxisSize,
                                 int64_t tileSize);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t batchIdx, int64_t offset, int64_t curLen);
    __aicore__ inline void Compute(int64_t curLen);
    __aicore__ inline void CopyOut(int64_t batchIdx, int64_t idxVal,
                                    int64_t offset, int64_t curLen);

private:
    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueueUpdates;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueueScales;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueueZp;
    TBuf<TPosition::VECCALC> fp32Buf1;
    TBuf<TPosition::VECCALC> fp32Buf2;
    TBuf<TPosition::VECCALC> tmpBuf;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueueResult;

    GlobalTensor<int8_t> inputGm_;
    GlobalTensor<int32_t> indicesGm_;
    GlobalTensor<T> updatesGm_;
    GlobalTensor<T_SCALE> scalesGm_;
    GlobalTensor<T_ZP> zpGm_;
    GlobalTensor<int8_t> outputGm_;

    int64_t outerSize_ = 0;
    int64_t innerSize_ = 0;
    int64_t axisSize_ = 0;
    int64_t updateAxisSize_ = 0;
    int64_t tileSize_ = 0;
    int64_t tailTileSize_ = 0;
    int64_t numTiles_ = 0;
};

template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Init(
    GM_ADDR inputGm, GM_ADDR indicesGm, GM_ADDR updatesGm, GM_ADDR scalesGm,
    GM_ADDR zpGm, GM_ADDR outputGm,
    int64_t outerSize, int64_t innerSize,
    int64_t axisSize, int64_t updateAxisSize,
    int64_t tileSize)
{
    outerSize_ = outerSize;
    innerSize_ = innerSize;
    axisSize_ = axisSize;
    updateAxisSize_ = updateAxisSize;
    tileSize_ = tileSize;

    numTiles_ = (innerSize_ + tileSize_ - 1) / tileSize_;
    int64_t lastTileLen = innerSize_ - (numTiles_ - 1) * tileSize_;
    tailTileSize_ = (lastTileLen > 0) ? lastTileLen : tileSize_;

    inputGm_.SetGlobalBuffer((__gm__ int8_t*)inputGm);
    indicesGm_.SetGlobalBuffer((__gm__ int32_t*)indicesGm);
    updatesGm_.SetGlobalBuffer((__gm__ T*)updatesGm);
    scalesGm_.SetGlobalBuffer((__gm__ T_SCALE*)scalesGm);
    zpGm_.SetGlobalBuffer((__gm__ T_ZP*)zpGm);
    outputGm_.SetGlobalBuffer((__gm__ int8_t*)outputGm);

    int64_t updAligned = ((tileSize_ * sizeof(T) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
    int64_t sclAligned = ((tileSize_ * sizeof(T_SCALE) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
    int64_t zpAligned = ((tileSize_ * sizeof(T_ZP) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
    int64_t fp32Aligned = ((tileSize_ * sizeof(float) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
    int64_t tAligned = ((tileSize_ * sizeof(T) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;
    int64_t outAligned = ((tileSize_ * sizeof(int8_t) + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES) * UB_ALIGN_BYTES;

    pipe.InitBuffer(inQueueUpdates, BUFFER_NUM, updAligned);
    pipe.InitBuffer(inQueueScales, BUFFER_NUM, sclAligned);
    if constexpr (HasZp) {
        pipe.InitBuffer(inQueueZp, BUFFER_NUM, zpAligned);
    }
    pipe.InitBuffer(fp32Buf1, fp32Aligned);
    pipe.InitBuffer(fp32Buf2, fp32Aligned);
    pipe.InitBuffer(tmpBuf, tAligned);
    pipe.InitBuffer(outQueueResult, BUFFER_NUM, outAligned);
}

template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::CopyIn(
    int64_t batchIdx, int64_t offset, int64_t curLen)
{
    int64_t updOffset = batchIdx * updateAxisSize_ * innerSize_ + offset;
    LocalTensor<T> updatesLocal = inQueueUpdates.AllocTensor<T>();
    DataCopyExtParams updParams;
    updParams.blockCount = 1;
    updParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
    DataCopyPad(updatesLocal, updatesGm_[updOffset], updParams);
    inQueueUpdates.EnQue(updatesLocal);

    LocalTensor<T_SCALE> scalesLocal = inQueueScales.AllocTensor<T_SCALE>();
    DataCopyExtParams sclParams;
    sclParams.blockCount = 1;
    sclParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T_SCALE));
    DataCopyPad(scalesLocal, scalesGm_[offset], sclParams);
    inQueueScales.EnQue(scalesLocal);

    if constexpr (HasZp) {
        LocalTensor<T_ZP> zpLocal = inQueueZp.AllocTensor<T_ZP>();
        DataCopyExtParams zpParams;
        zpParams.blockCount = 1;
        zpParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T_ZP));
        DataCopyPad(zpLocal, zpGm_[offset], zpParams);
        inQueueZp.EnQue(zpLocal);
    }
}

template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Compute(int64_t curLen)
{
    // 1. DeQue updates → Cast → fp32
    LocalTensor<T> updatesLocal = inQueueUpdates.DeQue<T>();
    LocalTensor<float> updatesFp32 = fp32Buf1.Get<float>();
    Cast(updatesFp32, updatesLocal, RoundMode::CAST_NONE, curLen);

    // 2. DeQue scales → fp32 (Cast if needed)
    LocalTensor<T_SCALE> scalesLocal = inQueueScales.DeQue<T_SCALE>();
    LocalTensor<float> scalesFp32;
    if constexpr (ScalesIsFp32) {
        scalesFp32 = scalesLocal.template ReinterpretCast<float>();
    } else {
        scalesFp32 = fp32Buf2.Get<float>();
        Cast(scalesFp32, scalesLocal, RoundMode::CAST_NONE, curLen);
    }

    // 3. Quantize: Div → fp32Buf1 (reuse, as updatesFp32 no longer needed)
    Div(updatesFp32, updatesFp32, scalesFp32, curLen);
    // updatesFp32 now holds quantFp32

    // 4. Optional Add zp
    if constexpr (HasZp) {
        LocalTensor<T_ZP> zpLocal = inQueueZp.DeQue<T_ZP>();
        LocalTensor<float> zpFp32 = fp32Buf2.Get<float>();
        Cast(zpFp32, zpLocal, RoundMode::CAST_NONE, curLen);
        Add(updatesFp32, updatesFp32, zpFp32, curLen);
        inQueueZp.FreeTensor(zpLocal);
    }

    // 5. Clamp to [-128, 127] using Relu trick:
    //    max(x, -128): Adds(+128) → Relu → Adds(-128)
    float f128 = 128.0f;
    Adds(updatesFp32, updatesFp32, f128, curLen);
    Relu(updatesFp32, updatesFp32, curLen);
    float nf128 = -128.0f;
    Adds(updatesFp32, updatesFp32, nf128, curLen);

    //    min(x, 127): 127 - Relu(127 - x)
    float f127 = 127.0f;
    // 127 - x: store in fp32Buf2
    Muls(updatesFp32, updatesFp32, -1.0f, curLen);
    Adds(updatesFp32, updatesFp32, f127, curLen);
    Relu(updatesFp32, updatesFp32, curLen);
    Muls(updatesFp32, updatesFp32, -1.0f, curLen);
    Adds(updatesFp32, updatesFp32, f127, curLen);
    // updatesFp32 now = clamp(x, -128, 127)

    // 6. Cast fp32 → T (half/bf16, with rounding)
    LocalTensor<T> quantHalf = tmpBuf.Get<T>();
    Cast(quantHalf, updatesFp32, RoundMode::CAST_ROUND, curLen);

    // 7. Cast T → int8 (with saturation to [-128, 127])
    LocalTensor<int8_t> resultInt8 = outQueueResult.AllocTensor<int8_t>();
    Cast(resultInt8, quantHalf, RoundMode::CAST_NONE, curLen);
    outQueueResult.EnQue(resultInt8);

    // 8. Free inputs
    inQueueUpdates.FreeTensor(updatesLocal);
    inQueueScales.FreeTensor(scalesLocal);
}

template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::CopyOut(
    int64_t batchIdx, int64_t idxVal, int64_t offset, int64_t curLen)
{
    LocalTensor<int8_t> resultInt8 = outQueueResult.DeQue<int8_t>();
    int64_t dstOffset = batchIdx * axisSize_ * innerSize_ + idxVal * innerSize_ + offset;

    DataCopyExtParams outParams;
    outParams.blockCount = 1;
    outParams.blockLen = static_cast<uint32_t>(curLen * sizeof(int8_t));
    DataCopyPad(outputGm_[dstOffset], resultInt8, outParams);
    outQueueResult.FreeTensor(resultInt8);
}

template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Process()
{
    int64_t blockIdx = GetBlockIdx();
    int64_t coreNum = (outerSize_ < MAX_CORES) ? outerSize_ : MAX_CORES;
    if (blockIdx >= coreNum) return;

    for (int64_t taskId = blockIdx; taskId < outerSize_; taskId += coreNum) {
        int32_t idxVal = indicesGm_.GetValue(taskId);

        for (int64_t t = 0; t < numTiles_ - 1; ++t) {
            int64_t offset = t * tileSize_;
            CopyIn(taskId, offset, tileSize_);
            Compute(tileSize_);
            CopyOut(taskId, idxVal, offset, tileSize_);
        }
        int64_t lastOffset = (numTiles_ - 1) * tileSize_;
        CopyIn(taskId, lastOffset, tailTileSize_);
        Compute(tailTileSize_);
        CopyOut(taskId, idxVal, lastOffset, tailTileSize_);
    }
}

// =========================== Kernel 入口 ============================

extern "C" __global__ __aicore__ void quant_scatter(
    GM_ADDR inputGm, GM_ADDR indicesGm,
    GM_ADDR updatesGm, GM_ADDR scalesGm, GM_ADDR zpGm, GM_ADDR outputGm,
    int64_t outerSize, int64_t innerSize,
    int64_t axisSize, int64_t updateAxisSize,
    int64_t tileSize,
    int64_t updatesIsBf16, int64_t hasZp)
{
    if (updatesIsBf16) {
        if (hasZp) {
            QuantScatterKernel<bfloat16_t, bfloat16_t, bfloat16_t, true, false> op;
            op.Init(inputGm, indicesGm, updatesGm, scalesGm, zpGm, outputGm,
                    outerSize, innerSize, axisSize, updateAxisSize, tileSize);
            op.Process();
        } else {
            QuantScatterKernel<bfloat16_t, bfloat16_t, bfloat16_t, false, false> op;
            op.Init(inputGm, indicesGm, updatesGm, scalesGm, zpGm, outputGm,
                    outerSize, innerSize, axisSize, updateAxisSize, tileSize);
            op.Process();
        }
    } else {
        if (hasZp) {
            QuantScatterKernel<half, float, int32_t, true, true> op;
            op.Init(inputGm, indicesGm, updatesGm, scalesGm, zpGm, outputGm,
                    outerSize, innerSize, axisSize, updateAxisSize, tileSize);
            op.Process();
        } else {
            QuantScatterKernel<half, float, int32_t, false, true> op;
            op.Init(inputGm, indicesGm, updatesGm, scalesGm, zpGm, outputGm,
                    outerSize, innerSize, axisSize, updateAxisSize, tileSize);
            op.Process();
        }
    }
}
