67	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
68	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Init(
69	    GM_ADDR inputGm, GM_ADDR indicesGm, GM_ADDR updatesGm, GM_ADDR scalesGm,
70	    GM_ADDR zpGm, GM_ADDR outputGm,
71	    int64_t outerSize, int64_t innerSize,
72	    int64_t axisSize, int64_t updateAxisSize,
