76	    innerSize_ = innerSize;
77	    axisSize_ = axisSize;
78	    updateAxisSize_ = updateAxisSize;
79	    tileSize_ = tileSize;
80	
81	    numTiles_ = (innerSize_ + tileSize_ - 1) / tileSize_;
82	    int64_t lastTileLen = innerSize_ - (numTiles_ - 1) * tileSize_;
83	    tailTileSize_ = (lastTileLen > 0) ? lastTileLen : tileSize_;
84	
85	    inputGm_.SetGlobalBuffer((__gm__ int8_t*)inputGm);
86	    indicesGm_.SetGlobalBuffer((__gm__ int32_t*)indicesGm);
87	    updatesGm_.SetGlobalBuffer((__gm__ T*)updatesGm);
