110	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
111	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::CopyIn(
112	    int64_t batchIdx, int64_t offset, int64_t curLen)
113	{
114	    int64_t updOffset = batchIdx * updateAxisSize_ * innerSize_ + offset;
115	    LocalTensor<T> updatesLocal = inQueueUpdates.AllocTensor<T>();
116	    DataCopyExtParams updParams;
117	    updParams.blockCount = 1;
118	    updParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
119	    AscendC::DataCopyPadExtParams<T> updPadParams{false, 0, 0, 0};
120	    AscendC::DataCopyPad(updatesLocal, updatesGm_[updOffset], updParams, updPadParams);
121	    inQueueUpdates.EnQue(updatesLocal);
122	
123	    LocalTensor<T_SCALE> scalesLocal = inQueueScales.AllocTensor<T_SCALE>();
124	    DataCopyExtParams sclParams;
125	    sclParams.blockCount = 1;
126	    sclParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T_SCALE));
127	    AscendC::DataCopyPadExtParams<T_SCALE> sclPadParams{false, 0, 0, 0};
128	    AscendC::DataCopyPad(scalesLocal, scalesGm_[offset], sclParams, sclPadParams);
129	    inQueueScales.EnQue(scalesLocal);
130	
131	    if constexpr (HasZp) {
132	        LocalTensor<T_ZP> zpLocal = inQueueZp.AllocTensor<T_ZP>();
133	        DataCopyExtParams zpParams;
134	        zpParams.blockCount = 1;
135	        zpParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T_ZP));
136	        AscendC::DataCopyPadExtParams<T_ZP> zpPadParams{false, 0, 0, 0};
137	        AscendC::DataCopyPad(zpLocal, zpGm_[offset], zpParams, zpPadParams);
138	        inQueueZp.EnQue(zpLocal);
139	    }
140	}
