142	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
143	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Compute(int64_t curLen)
144	{
145	    // 1. DeQue updates → Cast → fp32
146	    LocalTensor<T> updatesLocal = inQueueUpdates.DeQue<T>();
147	    LocalTensor<float> updatesFp32 = fp32Buf1.Get<float>();
148	    Cast(updatesFp32, updatesLocal, RoundMode::CAST_NONE, curLen);
149	
150	    // 2. DeQue scales
151	    LocalTensor<T_SCALE> scalesLocal = inQueueScales.DeQue<T_SCALE>();
152	    LocalTensor<float> scalesFp32 = fp32Buf2.Get<float>();
153	    if constexpr (ScalesIsFp32) {
154	        // scales already fp32, copy via Muls(float,float) which is supported
155	        Muls(scalesFp32, scalesLocal, 1.0f, curLen);
156	    } else {
157	        Cast(scalesFp32, scalesLocal, RoundMode::CAST_NONE, curLen);
158	    }
159	
160	    // 3. Quantize: Div → fp32Buf1 (reuse)
161	    Div(updatesFp32, updatesFp32, scalesFp32, curLen);
162	
163	    // 4. Optional Add zp
164	    if constexpr (HasZp) {
165	        LocalTensor<T_ZP> zpLocal = inQueueZp.DeQue<T_ZP>();
166	        // Cast zp to fp32Buf2 (reuse, scalesFp32 no longer needed after Div)
167	        Cast(scalesFp32, zpLocal, RoundMode::CAST_NONE, curLen);
168	        Add(updatesFp32, updatesFp32, scalesFp32, curLen);
169	        inQueueZp.FreeTensor(zpLocal);
170	    }
171	
172	    // 5. Clamp to [-128, 127]:
173	    // max(x, -128): Adds(+128) → Relu → Adds(-128)
174	    float f128 = 128.0f;
175	    Adds(updatesFp32, updatesFp32, f128, curLen);
176	    Relu(updatesFp32, updatesFp32, curLen);
177	    float nf128 = -128.0f;
178	    Adds(updatesFp32, updatesFp32, nf128, curLen);
179	
180	    // min(x, 127): 127 - Relu(127 - x)
181	    Muls(updatesFp32, updatesFp32, -1.0f, curLen);
182	    float f127 = 127.0f;
183	    Adds(updatesFp32, updatesFp32, f127, curLen);
184	    Relu(updatesFp32, updatesFp32, curLen);
185	    Muls(updatesFp32, updatesFp32, -1.0f, curLen);
186	    Adds(updatesFp32, updatesFp32, f127, curLen);
187	
188	    // 6. Cast fp32 → half (rounding), then half → int8
189	    LocalTensor<half> quantHalf = tmpBuf.Get<half>();
190	    Cast(quantHalf, updatesFp32, RoundMode::CAST_ROUND, curLen);
191	
192	    LocalTensor<int8_t> resultInt8 = outQueueResult.AllocTensor<int8_t>();
193	    Cast(resultInt8, quantHalf, RoundMode::CAST_NONE, curLen);
194	    outQueueResult.EnQue(resultInt8);
195	
196	    // 7. Free inputs
197	    inQueueUpdates.FreeTensor(updatesLocal);
198	    inQueueScales.FreeTensor(scalesLocal);
199	}
