201	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
202	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::CopyOut(
203	    int64_t batchIdx, int64_t idxVal, int64_t offset, int64_t curLen)
204	{
205	    LocalTensor<int8_t> resultInt8 = outQueueResult.DeQue<int8_t>();
206	    int64_t dstOffset = batchIdx * axisSize_ * innerSize_ + idxVal * innerSize_ + offset;
207	
208	    DataCopyExtParams outParams;
209	    outParams.blockCount = 1;
210	    outParams.blockLen = static_cast<uint32_t>(curLen * sizeof(int8_t));
211	    AscendC::DataCopyPad(outputGm_[dstOffset], resultInt8, outParams);
212	    outQueueResult.FreeTensor(resultInt8);
213	}
