215	template<typename T, typename T_SCALE, typename T_ZP, bool HasZp, bool ScalesIsFp32>
216	__aicore__ inline void QuantScatterKernel<T, T_SCALE, T_ZP, HasZp, ScalesIsFp32>::Process()
217	{
218	    int64_t blockIdx = GetBlockIdx();
219	    int64_t coreNum = (outerSize_ < MAX_CORES) ? outerSize_ : MAX_CORES;
220	    if (blockIdx >= coreNum) return;
221	
222	    for (int64_t taskId = blockIdx; taskId < outerSize_; taskId += coreNum) {
223	        int32_t idxVal = indicesGm_.GetValue(taskId);
224	
225	        for (int64_t t = 0; t < numTiles_ - 1; ++t) {
226	            int64_t offset = t * tileSize_;
227	            CopyIn(taskId, offset, tileSize_);
228	            Compute(tileSize_);
229	            CopyOut(taskId, idxVal, offset, tileSize_);
230	        }
231	        int64_t lastOffset = (numTiles_ - 1) * tileSize_;
232	        CopyIn(taskId, lastOffset, tailTileSize_);
233	        Compute(tailTileSize_);
234	        CopyOut(taskId, idxVal, lastOffset, tailTileSize_);
235	    }
236	}
