        } else {
            QuantScatterKernel<half, float, int32_t, false, true> op;
            op.Init(inputGm, indicesGm, updatesGm, scalesGm, zpGm, outputGm,
                    outerSize, innerSize, axisSize, updateAxisSize, tileSize);
            op.Process();
        }
    }
}
